#include "symrep_bootstrap.hpp"
using namespace symrep;
int main(int argc,char**argv){try{require(argc==3,"usage suffix_TR_embedding OUT TR_basis");fs::path out=argv[1];auto start=std::chrono::steady_clock::now();rref_option_t opt;opt->pool.reset(1);auto tf=read_matrix(out/"lastpair_TF15.wxf"),tr=flatten(read(argv[2]));require(tf.nrow==15&&tf.ncol==88&&tr.nrow==12&&tr.ncol==88,"one-letter shape");auto B=mul(flatten(read(out/"LEC_2.wxf")),kron(identity(88),tf)),C=mul(flatten(read(out/"LEC_TR_2.wxf")),kron(identity(88),tr));require(B.nrow==175&&C.nrow==92&&B.ncol==7744&&C.ncol==7744,"two-letter shape");Chart cb(B,opt),cc(C,opt);auto J=cb.coordinates(C);require(equal(mul(J,B),C),"all physical pair coordinates J TF2 = TR2");write(out/"suffix_TR92_to_TF175.wxf",J);write(out/"suffix_TR92_physical.wxf",C);write(out/"suffix_TF175_physical.wxf",B);write(out/"suffix_TR12_basis.wxf",tr);std::vector<std::string> names{"cycmat","flipmat","galois1a","galois1b","galois2a","galois2b","galois3"};std::vector<Mat> at,af;
 for(auto name:names){auto g=read_matrix(out/"data"/(name+".wxf"));auto gg=kron(g,g);auto a=cc.coordinates(mul(C,gg)),b=cb.coordinates(mul(B,gg));require(equal(mul(a,J),mul(J,b)),"TR/TF intertwiner");write(out/"actions"/("suffix_TR_"+name+"_w2.wxf"),a);write(out/"actions"/("suffix_TF_audit_"+name+"_w2.wxf"),b);at.push_back(std::move(a));af.push_back(std::move(b));std::cout<<"ACTION "<<name<<" full_physical_intertwiner=pass suffix_embedding_intertwiner=pass seconds="<<seconds(start)<<std::endl;}
 auto cyc2=mul(at[0],at[0]);require(equal(mul(cyc2,cyc2),identity(92)),"C4");require(equal(mul(at[1],at[1]),identity(92)),"reflection");require(equal(mul(mul(at[1],at[0]),at[1]),mul(cyc2,at[0])),"dihedral");for(size_t k=2;k<7;++k){require(equal(mul(at[k],at[k]),identity(92)),"Galois involution");for(size_t l=2;l<k;++l)require(equal(mul(at[k],at[l]),mul(at[l],at[k])),"Galois commuting");}
 auto E=read_matrix(out/"lastpair_E.wxf");require(mul(J,E).nnz()==0,"homogeneous TR tail residual");std::ofstream j(out/"suffix_TR_embedding.json");j<<"{\"all_checks_pass\":true,\"J_dimensions\":[92,175],\"J_nonzeros\":"<<J.nnz()<<",\"physical_pair_axes\":[88,88],\"full_exact_pair_equality\":\"J.TF2=TR2\",\"full_exact_actions\":7,\"D4_relations_pass\":true,\"Galois_involutions_and_commutativity_pass\":true,\"all_embedding_intertwiners_pass\":true,\"J_times_tail_map_E_zero\":true,\"complete_homogeneous_local_tail_kernel\":true,\"dimension_certificate\":\"rankJ=92=175-rankE, rankE=83 independently certified\",\"basis_method\":\"General exact coordinate charts with full physical7744-column reconstruction, no orthonormality assumption\",\"TR_basis_source\":\""<<argv[2]<<"\",\"scope\":\"Local homogeneous suffix embedding and exact symmetry actions only. Global seam and affine existence remain pending.\",\"seconds\":"<<seconds(start)<<"}\n";std::cout<<"COMPLETE J_nnz="<<J.nnz()<<" seconds="<<seconds(start)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
